//! L08-I: the GPU simple_fx family and hqBloom on the real headless Metal
//! compositor, compared with literals from the baseline oracle.
//!
//! `fixtures/scene-effect-gpu-fx/oracle.txt` was generated by
//! `tools/gen_scene_effect_gpu_fx_oracle.js` from the baseline `simple_fx.wgsl`
//! (hand transliteration guarded by whole-block text assertions), the accepted
//! L08-H model of `blend.wgsl`, `blur.wgsl`, `color_adjust.wgsl` and
//! `vignette.wgsl`, and the `run_one_effect` arms of `geometry-wasm/src/engine.rs`
//! at fbe4b8a3: 35 stacks on 16x16 and 20x12 canvases, every texture write
//! quantised to RGBA8. The GPU result is the actual
//! `Compositor::apply_effect_stack` / `apply_effect_stack_into` readback of a plan
//! produced by the real L08-C planner from the oracle's own effect lines and
//! admitted with the oracle's own frame (box and time). Tolerance per case is in
//! oracle steps (1 for a per-pixel remap, 2 for a sampling effect or a short
//! stack, 3 for hqBloom or a stack with a blur), measured on alpha and on
//! premultiplied colour. Metal readback is never an installed result.
use super::support::{check_case, headless, oracle, parse, run_case, run_group, ORACLE};

const SHADER: &str = include_str!("../../geometry-wasm/src/simple_fx.wgsl");

const BUILT_INS: [&str; 14] = [
    "sepia",
    "invert",
    "grayscale",
    "posterize",
    "pixelate",
    "chromaticAberration",
    "scanlines",
    "grain",
    "sharpen",
    "edgeDetect",
    "groundShadow",
    "contourBrut",
    "threshold",
    "halftone",
];

#[test]
fn oracle_is_well_formed_and_every_case_has_a_full_expected_image() {
    let oracle = parse(ORACLE);
    assert_eq!(oracle.images.len(), 5);
    assert_eq!(oracle.cases.len(), 35);
    assert_eq!(oracle.mutations.len(), 8);
    for case in &oracle.cases {
        let image = oracle.image(&case.image);
        assert_eq!(case.expect.len(), image.bytes.len(), "{}", case.name);
        assert!(!case.effects.is_empty(), "{}", case.name);
        assert!(matches!(case.tol, 1..=3), "{}", case.name);
        assert!(case.passes >= 1, "{}", case.name);
    }
    let names: std::collections::HashSet<&str> =
        oracle.cases.iter().map(|c| c.name.as_str()).collect();
    assert_eq!(names.len(), oracle.cases.len(), "case names are unique");
    let count = |prefix: &str| {
        oracle
            .cases
            .iter()
            .filter(|c| c.name.starts_with(prefix))
            .count()
    };
    assert_eq!(count("fx-"), 21);
    assert_eq!(count("bloom-"), 6);
    assert_eq!(count("mix-"), 8);
    // Both entry variants, both landing buffers, a non-canvas box and a non-zero time.
    assert!(oracle.cases.iter().any(|c| c.into) && oracle.cases.iter().any(|c| !c.into));
    assert!(oracle
        .cases
        .iter()
        .any(|c| c.bbox.2 != c.bbox.3 && c.bbox.0 != 0.0));
    assert!(oracle.cases.iter().any(|c| c.time != 0.0));
    // Every built-in, hqBloom and the unknown-type fallback appear in a case.
    let has = |kind: &str| {
        oracle
            .cases
            .iter()
            .any(|c| c.effects.iter().any(|e| e.effect_type == kind))
    };
    for kind in BUILT_INS
        .iter()
        .chain(&["hqBloom", "hqbloom", "blur", "glow"])
    {
        assert!(has(kind), "no oracle case runs {kind}");
    }
}

#[test]
fn oracle_header_pins_the_baseline_sources() {
    for pin in [
        "# baseline commit fbe4b8a33e6d5a229f014154df2ba21988a9fabc",
        "# sha256 simple_fx.wgsl (whole) = d325343daa8f212bedcbc439c6382292f1f9cb9a09512dc019fa651dca9a5904",
        "# sha256 blend.wgsl (whole) = b928fda02ee59558fffc226e9edfe3fbe24949b2d2e3d097b428987b17691ded",
        "# sha256 blur.wgsl (whole) = 05f6337233ca1219964113f1c012877d84cfed2e715a1e4c987ae606eb342145",
        "# sha256 color_adjust.wgsl (whole) = 0dc722f4bf896a5b9321b0ab68875901d44eb8bec82b064673d02c4f19f5e874",
        "# sha256 vignette.wgsl (whole) = 69559256655123fad9aa30e4aa8aec807d9a2fe943ddb4a7090b0b717af85226",
        "# sha256 engine.rs run_one_effect = 73dd19b62c113e0448e227eddf0adb09a09d1bd5dd698923f756e761dcd1caaf",
        "# sha256 geometry-wasm/src/engine.rs (whole) = 1a5e3729dc57922e9c91aa8d4782572f920bc291de331332f4b03b2a27f1cc64",
    ] {
        assert!(ORACLE.lines().any(|line| line == pin), "{pin}");
    }
}

#[test]
fn the_compiled_in_shader_still_has_the_layout_the_payload_assumes() {
    // The shader that include_str! compiles in (not a copy): the uniform struct holds the first
    // twelve payload slots in this order (bytes 48..64 are read by custom effects only), and
    // the effect ids the planner emits are the shader's constants.
    let params = SHADER.find("struct Params {").expect("Params struct");
    let mut at = params;
    for field in [
        "effect_id: f32",
        "p1: f32",
        "p2: f32",
        "p3: f32",
        "tex_w: f32",
        "tex_h: f32",
        "time: f32",
        "p4: f32",
        "bbox_x: f32",
        "bbox_y: f32",
        "bbox_w: f32",
        "bbox_h: f32",
    ] {
        let found = SHADER[at..]
            .find(field)
            .unwrap_or_else(|| panic!("field {field} out of order or missing"));
        at += found + field.len();
    }
    assert!(
        !SHADER[params..at].contains("p5"),
        "the built-in struct stops at the box"
    );
    for (name, id) in [
        ("SEPIA", 0),
        ("INVERT", 1),
        ("GRAYSCALE", 2),
        ("POSTERIZE", 3),
        ("PIXELATE", 4),
        ("CHROMATIC_ABERRATION", 5),
        ("SCANLINES", 6),
        ("GRAIN", 7),
        ("SHARPEN", 8),
        ("EDGE_DETECT", 9),
        ("GROUND_SHADOW", 10),
        ("CONTOUR_BRUT", 11),
        ("THRESHOLD", 12),
        ("HALFTONE", 13),
        ("BLOOM_EXTRACT", 14),
    ] {
        let line = format!("const EFFECT_{name}: f32 = {id}.0;");
        assert!(SHADER.contains(&line), "{line}");
    }
    assert!(
        !SHADER.contains("params.bbox_"),
        "no built-in reads the box: a different frame cannot change a built-in's pixels"
    );
}

#[test]
fn gpu_per_pixel_and_sampling_effects_match_the_baseline_oracle() {
    assert_eq!(run_group("fx-"), 21);
}

#[test]
fn gpu_hqbloom_extract_blur_screen_chain_matches_the_baseline_oracle() {
    assert_eq!(run_group("bloom-"), 6);
}

#[test]
fn gpu_mixed_stacks_follow_the_plan_order_landing_and_entry_variant() {
    assert_eq!(run_group("mix-"), 8);
}

#[test]
fn gpu_one_compositor_runs_every_case_repeatedly_with_identical_pixels() {
    // The pipelines are built once and shared (the simple_fx pipeline on its first use); a
    // second pass over the same compositor must reproduce the first byte for byte.
    let mut gpu = headless();
    let oracle = oracle();
    let first: Vec<Vec<u8>> = oracle
        .cases
        .iter()
        .map(|case| run_case(&mut gpu, case, oracle.image(&case.image)).bytes)
        .collect();
    for (case, before) in oracle.cases.iter().zip(&first) {
        let image = oracle.image(&case.image);
        let again = run_case(&mut gpu, case, image).bytes;
        assert_eq!(&again, before, "{} is not repeatable", case.name);
        check_case(case, image.w, &again).unwrap();
    }
}
